-- BliGO : Top des librairies de novembre 2026 (27/11/2026, demande de Mégane)
-- Liste donnée par Mégane, vérifiée titre par titre (Google Books + presse) :
-- 25 titres, « Au pays des vivants » (C. Beauvais) retiré car introuvable.
-- Ajoute aux sélections mensuelles un rayon (section) et un conseil d'achat
-- (note), et passe le rang maximum de 20 à 50.

alter table public.monthly_top_books add column if not exists section text;
alter table public.monthly_top_books add column if not exists note text;
alter table public.monthly_top_books drop constraint if exists monthly_top_books_rank_check;
alter table public.monthly_top_books add constraint monthly_top_books_rank_check check (rank between 1 and 50);

delete from public.monthly_top_books where month = '2026-11-01';
